package A5;
import java.sql.*;
public class WalletTransfer{public static void transfer(Connection c,String from,String to,double amount)throws SQLException{if(amount<=0)throw new IllegalArgumentException("Amount must be positive");boolean old=c.getAutoCommit();c.setAutoCommit(false);try{try(PreparedStatement d=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE wallet_id=? AND balance>=?")){d.setDouble(1,amount);d.setString(2,from);d.setDouble(3,amount);if(d.executeUpdate()!=1)throw new SQLException("Insufficient funds or missing source");}try(PreparedStatement a=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE wallet_id=?")){a.setDouble(1,amount);a.setString(2,to);if(a.executeUpdate()!=1)throw new SQLException("Destination wallet missing");}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}}}
